-- =====================================================================
-- Import: WTS official tusker list (323 tuskers, from Full_list.xlsx → "Base" sheet)
--
-- Run in Supabase SQL Editor AFTER migration 20261114010000_tusker_registry_fields.sql.
--
-- 1. Removes the 20 demo tuskers that came with the starter data
--    (matched by ID + demo Sinhala name, so real edits are never deleted).
-- 2. Inserts every tusker on the list, or updates the list fields of ones
--    that already exist. Descriptions, photos, Sinhala names etc. that you
--    add later in the admin portal are kept if you re-run this.
-- =====================================================================
begin;

delete from public.tuskers
where (id, sinhala) in (('T304', 'නීරෝ'), ('T303', 'රුද්‍රජ'), ('T302', 'පුලින'), ('T301', 'ප්‍රහස්ථ'), ('T300', 'මඩුලු'), ('T299', 'ආර්ය'), ('T298', 'සඳගිරි'), ('T297', 'ලංකේශ්වර'), ('T296', 'ගජේන්ද්‍ර'), ('T295', 'සුමේධ'), ('T294', 'නන්දිමිත්‍ර'), ('T293', 'ගජබා'), ('T292', 'රාවණා'), ('T291', 'වෙහෙරගල'), ('T290', 'මාලිගාව'), ('T289', 'තිස්ස'), ('T288', 'උතුරු'), ('T287', 'සිංහරාජ'), ('T286', 'දළදාපති'), ('T285', 'කුරුවිට'));

on conflict (id) do update set
  name = excluded.name,
  location = excluded.location,
  living_status = excluded.living_status,
  death_year = excluded.death_year,
  death_reason = excluded.death_reason,
  last_seen_area = excluded.last_seen_area,
  zone = excluded.zone,
  district = excluded.district,
  province = excluded.province,
  last_seen = excluded.last_seen,
  age_range = excluded.age_range,
  health_condition = excluded.health_condition,
  threat_level = excluded.threat_level,
  remarks = excluded.remarks;

commit;

-- Check: expect 323 rows
select living_status, count(*) from public.tuskers group by living_status order by 1;
